p='src/lib/i18n/messages.json'
d=json.load(open(p))
need=json.load(open('tmpscripts/missing.json'))
print("still missing:",[k for k in need if k not in T and k not in d])
added=0
for k,v in T.items():
    assert len(v)==7,k
    if k not in d: d[k]=v; added+=1
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+"\n")
print("added",added,"total",len(d))
